{
  "name": "pr-watch",
  "version": "0.3.0",
  "description": "Watches gate, reviews and post-merge pipelines of Azure DevOps and GitHub pull requests",
  "author": {
    "name": "heidiks"
  },
  "homepage": "https://github.com/heidiks/agent-kit",
  "license": "MIT",
  "types": "./types/index.d.ts",
  "userConfig": {
    "ado": {
      "type": "boolean",
      "title": "Azure DevOps",
      "description": "Watch Azure DevOps pull requests (az CLI)",
      "default": true
    },
    "github": {
      "type": "boolean",
      "title": "GitHub",
      "description": "Watch GitHub pull requests (gh CLI)",
      "default": true
    },
    "githubHosts": {
      "type": "string",
      "title": "GitHub hosts",
      "description": "Comma-separated hosts to accept; add your GitHub Enterprise host (gh must be logged in there)",
      "default": "github.com"
    },
    "details": {
      "type": "boolean",
      "title": "Failure details and stages",
      "description": "Fetch the build timeline (ADO) and check annotations (GitHub); one extra call per build",
      "default": true
    },
    "currentBranch": {
      "type": "boolean",
      "title": "Current branch PR",
      "description": "On session start, watch the open PR of the current branch",
      "default": true
    },
    "maxRows": {
      "type": "number",
      "title": "PRs in the band",
      "description": "How many PRs the band shows before collapsing the rest into a +N more button that opens the full list",
      "default": 5
    },
    "notify": {
      "type": "string",
      "title": "System notifications",
      "description": "off, important (failures, changes requested, pending approvals, merges, finished deploys) or all (every state change)",
      "options": [
        "off",
        "important",
        "all"
      ],
      "default": "important"
    },
    "tasks": {
      "type": "boolean",
      "title": "Spec tasks",
      "description": "Read docs/prd task files (spec-driven-dev) to link PRs to tasks, show plans in the overview and watch PRs of tasks in review",
      "default": true
    }
  }
}
